CREATE TABLE "ai_trials" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "granted_count" INTEGER NOT NULL DEFAULT 30,
    "used_count" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_ai_trials_user_id" UNIQUE ("user_id")
);

INSERT INTO "ai_trials" ("user_id", "granted_count", "used_count", "created_at", "updated_at")
SELECT "user_id", 30, COUNT(*), NOW(), NOW()
FROM "ai_analyses"
WHERE "status" = 'COMPLETED'
GROUP BY "user_id";
